// Generates src/schema.ts from docs/architecture/openapi-v1.yaml.
// Usage: node scripts/generate.mjs [--check]
import { readFileSync, writeFileSync } from 'node:fs';
import openapiTS, { astToString } from 'openapi-typescript';

const spec = new URL('../../../docs/architecture/openapi-v1.yaml', import.meta.url);
const out = new URL('../src/schema.ts', import.meta.url);
const banner =
  '// Code generated by scripts/generate.mjs from docs/architecture/openapi-v1.yaml. DO NOT EDIT.\n\n';

const content = banner + astToString(await openapiTS(spec));

if (process.argv.includes('--check')) {
  let current = '';
  try {
    current = readFileSync(out, 'utf8');
  } catch {
    // missing file counts as stale
  }
  if (current !== content) {
    console.error('src/schema.ts is stale; run pnpm --filter @pcp/api-client generate');
    process.exit(1);
  }
} else {
  writeFileSync(out, content);
}
